/**
 * Стадия `build_env` — первая из двух линий обороны против A12 (утечка секретов из env
 * в вывод) и реализация инварианта И4 `docs/02-architecture.md`.
 *
 * **Allowlist, а не deny-лист.** Список запрещённых имён невозможно дописать до полноты:
 * имена переменных на машине разработчика заранее не известны, а каждый новый CI-провайдер
 * приносит свои. Отрицание тут — не стилистика, а разница между «секрет не попал в процесс»
 * и «секрет, о котором мы подумали, не попал в процесс».
 *
 * Функция чистая и берёт окружение аргументом, а не читает `process.env`: вызывающий (E3)
 * знает, окружение какого процесса он передаёт, а тест не имеет права зависеть от машины.
 */

import type { AuditEvent } from '@mcpproxy/contracts';

/**
 * Значение `PATH` для дочернего процесса, когда своего у него нет.
 *
 * Почему `PATH` вообще есть, если `exec[0]` резолвит демон (E2): резолв закрывает A4 —
 * запуск не того бинаря по подменённому `PATH`. Но дочерний процесс делает **свои**
 * под-вызовы (`pnpm test` зовёт `node`, `git`, `sh`), и без `PATH` они падают не по делу.
 * Минимальный системный список — компромисс: под-вызовы работают, каталоги пользователя
 * в поиск не входят.
 */
export const MINIMAL_PATH = '/usr/bin:/bin:/usr/sbin:/sbin';

export interface BuiltEnv {
  /** Окружение дочернего процесса. Свежий объект: мутация не достаёт до источника. */
  readonly env: Record<string, string>;
  /**
   * Ссылкой на контракт, а не повторением его формы: структурная копия совпадала бы сегодня
   * и разошлась бы молча, когда E0 сдвинет форму. Имена для `AuditEvent.env.allowed` —
   * отсортированные, без дублей.
   *
   * Это то, что процесс **получил**, а не то, что было запрошено: разрешённое, но не
   * заданное имя сюда не попадает. Запись аудита читают через месяцы, и вопрос к ней
   * всегда «что было у процесса»; запрошенную политику восстанавливают из снапшота рецепта
   * в lock, который хранит её целиком именно для этого (R28 из E0).
   *
   * **Только имена.** Значение переменной не попадает в событие ни при каких условиях.
   */
  readonly allowed: NonNullable<AuditEvent['env']>['allowed'];
}

/**
 * Собирает окружение дочернего процесса по allowlist.
 *
 * @param allow — эффективный `env.allow` рецепта. Его уже посчитал E0 как **пересечение**
 * с `defaults.env.allow` (`normalizeRecipe(...).effective`), поэтому здесь не может
 * появиться имя, которого владелец манифеста не разрешал, и пересчитывать слияние тут
 * нечего — вторая копия правила разошлась бы с первой на первой же правке.
 * @param source — окружение, из которого берутся значения; обычно `process.env` демона.
 * @param injected — переменные, которые добавляет **режим песочницы**, минуя allowlist.
 *
 * Третий параметр существует потому, что два режима E3 устроены по-разному, и без него
 * фильтр противоречил бы сам себе: в `seatbelt` прокси-переменные вшивает в строку команды
 * сам `srt`, значит `injected` пуст; в `none` seatbelt-обёртки нет вовсе, и прокси-переменные
 * вместе с переменными доверия к CA обязан передать режим.
 *
 * Мимо allowlist — намеренно: это не переменные рецепта, а механика песочницы, и провести их
 * через фильтр значило бы дать манифесту право отключить наблюдение за собственной сетью.
 */
export function buildEnv(
  allow: readonly string[],
  source: Readonly<Record<string, string | undefined>>,
  injected: Readonly<Record<string, string | undefined>> = {},
): BuiltEnv {
  // `Object.create(null)`, а не литерал: имя `__proto__`, пришедшее из манифеста, иначе
  // попало бы в СЕТТЕР `Object.prototype` вместо ключа — значение молча исчезло бы, а при
  // недоброжелательном `source` (например, разобранном из JSON) присваивание задело бы
  // прототип. Манифест весь остальной E6 считает недоверенным входом; здесь так же.
  const env: Record<string, string> = Object.create(null);

  for (const name of allow) {
    // `Object.hasOwn`, а не `source[name]`: индексирование идёт по ЦЕПОЧКЕ ПРОТОТИПОВ, и
    // `allow: ['toString']` при пустом окружении клало в результат функцию — то есть имя,
    // которого в окружении нет, приезжало ключом (прямое нарушение R2), да ещё с
    // нестроковым значением в типе `Record<string, string>`, который E3 отдаёт `spawn`,
    // а запись аудита при этом утверждала, что у процесса была такая переменная.
    if (!Object.hasOwn(source, name)) continue;

    const value = source[name];
    // `undefined` — «имя не задано», и оно обязано ОТСУТСТВОВАТЬ как ключ, а не приезжать
    // пустой строкой: `spawn` различает эти два случая, и потребители тоже — `git` с
    // `GIT_DIR=''` ведёт себя не как `git` без `GIT_DIR`. Пустая строка, наоборот, —
    // заданное значение, и она проходит. Не-строка отбрасывается по той же причине, что и
    // унаследованное свойство: в окружении процесса строк не бывает других типов.
    if (typeof value !== 'string') continue;
    env[name] = value;
  }

  // Всегда последним и **без оглядки на лист**: константа побеждает всегда, даже когда
  // рецепт назвал `PATH` в `allow`.
  //
  // Прежняя редакция наследовала `PATH` из окружения, если он был разрешён и задан, и это
  // расходилось с D10 её же спеки («всегда минимальный»), с R23 эпика песочницы и с
  // `docs/02-architecture.md:70`. Расхождение било по КАНОНИЧЕСКОМУ примеру
  // `docs/07-contracts.md:35`, где `allow` содержит `PATH`: рецепт, назвавший переменную
  // ради переносимости, тихо получал путь поиска демона — тот самый, который собирает
  // direnv из каталога проекта и в который заезжают приватные тулчейны. То есть одно и то
  // же имя в листе значило разное в зависимости от машины разработчика.
  //
  // Цена решения записана: под-вызовы дочернего процесса не видят тулчейн проекта. Сам
  // `exec[0]` от этого не страдает — его резолвит в абсолютный путь валидатор (A4).
  env.PATH = MINIMAL_PATH;

  // Инъекция режима — после фильтра и после `PATH`: она перекрывает и то и другое, потому
  // что описывает не рецепт, а устройство песочницы вокруг него.
  for (const [name, value] of Object.entries(injected)) {
    if (typeof value === 'string') env[name] = value;
  }

  return { env, allowed: Object.keys(env).sort() };
}
